1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type ScenarioResults = {
19	  results: unknown[];
20	};
21	
22	const PROCESSING_FEE = 5;
23	
24	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	};
31	
32	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
33	
34	const addPercent = (amount: number, percent: number): number =>
35	  amount + (amount * percent) / 100;
36	
37	const policyBasePremium = (items: Item[]): number =>
38	  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
39	
40	const quotePremium = (items: Item[]): number =>
41	  Math.ceil(
42	    addPercent(policyBasePremium(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
43	      PROCESSING_FEE,
44	  );
45	
46	export const runScenario = (scenario: Scenario): ScenarioResults => ({
47	  results: scenario.steps.map((step) => ({
48	    premium: quotePremium(step.items ?? []),
49	  })),
50	});
