const roundPremiumInMHPCOsFavor = (amount: number): number =>
  Math.ceil(amount);

const quotePremium = (items: Item[]): number =>
  roundPremiumInMHPCOsFavor(
    addPercent(policyBasePremium(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
      PROCESSING_FEE,
  );
